/*
 * Mirage documentation — client-side search dialog.
 *
 * Dependency-free search over docs/search.json (generated by
 * tools/build_search.py; anchors there replicate the live kramdown
 * GFM heading ids, so #section deep links land on the right heading).
 *
 * Everything here is defensive, like site.js: this script must never
 * throw, on any browser, in any theme. Any fetch or parse failure sets
 * data-search-off on <html> (the header button hides via CSS) and the
 * dialog closes — the site keeps working without search.
 *
 *   Open:    header button, Cmd/Ctrl+K anywhere, "/" outside inputs.
 *   Close:   Esc, the Esc button, a click on the backdrop.
 *   Keys:    up/down move (wrap), Enter opens the active result,
 *            Tab stays inside the dialog, focus returns to the opener.
 *   Scoring: per term — title 8, heading 5, body 1 — summed; every
 *            term must match somewhere (multi-term AND). Top 9 results,
 *            grouped by nav section, best-matched section highlighted.
 *   Markup:  results, snippets and <mark> highlights are built with
 *            createElement/textContent only — no innerHTML anywhere.
 */
(function () {
  "use strict";

  var DEBOUNCE_MS = 120;
  var MAX_RESULTS = 9;

  var INDEX = null;        // fetched once on first open, cached in memory
  var BUS = null;          // { lowerTitle, sections:[{id,heading,text,lowerHeading,lowerText}] }
  var BASE = "";           // site baseurl, baked into the overlay element
  var RESULTS = [];        // current result rows
  var ACTIVE = -1;         // active option, -1 = none
  var OPENER = null;       // element to restore focus to on close
  var TIMER = null;        // input debounce

  function $(id) { return document.getElementById(id); }

  function ready(fn) {
    if (document.readyState !== "loading") fn();
    else document.addEventListener("DOMContentLoaded", fn);
  }

  /* ---------- failure mode: silent disable ---------- */

  function disable() {
    try { document.documentElement.setAttribute("data-search-off", ""); } catch (e) { /* inert */ }
  }

  /* ---------- index loading ---------- */

  function loadIndex(done) {
    if (INDEX) { done(true); return; }
    var overlay = $("search-overlay");
    var src = overlay && overlay.getAttribute("data-search-src");
    if (!src) { disable(); done(false); return; }
    try {
      fetch(src).then(function (res) {
        if (!res.ok) throw new Error("http " + res.status);
        return res.json();
      }).then(function (data) {
        try {
          INDEX = data && data.pages ? data : null;
          if (!INDEX) throw new Error("no pages in index");
          BUS = [];
          for (var i = 0; i < INDEX.pages.length; i++) {
            var p = INDEX.pages[i];
            var secs = [];
            for (var j = 0; j < p.sections.length; j++) {
              var s = p.sections[j];
              secs.push({
                id: s.id, heading: s.heading, text: s.text,
                lowerHeading: s.heading.toLowerCase(),
                lowerText: s.text.toLowerCase()
              });
            }
            BUS.push({
              url: p.url, title: p.title, description: p.description,
              section: p.section, lowerTitle: p.title.toLowerCase(),
              sections: secs
            });
          }
          done(true);
        } catch (e) { disable(); done(false); }
      }).catch(function () { disable(); done(false); });
    } catch (e) { disable(); done(false); }
  }

  /* ---------- scoring ---------- */

  function score(query) {
    var terms = query.toLowerCase().split(/\s+/);
    var clean = [];
    for (var i = 0; i < terms.length; i++) if (terms[i]) clean.push(terms[i]);
    if (!clean.length) return [];
    var out = [];
    for (var p = 0; p < BUS.length; p++) {
      var page = BUS[p];
      var total = 0;
      var matched = true;
      var best = null;
      for (var t = 0; t < clean.length && matched; t++) {
        var term = clean[t];
        var inTitle = page.lowerTitle.indexOf(term) !== -1;
        var inHeading = false;
        var inBody = false;
        var contribution = 0;
        for (var s = 0; s < page.sections.length; s++) {
          var sec = page.sections[s];
          var secHit = 0;
          if (sec.lowerHeading.indexOf(term) !== -1) { inHeading = true; secHit += 5; }
          if (sec.lowerText.indexOf(term) !== -1) { inBody = true; secHit += 1; }
          if (secHit > 0 && (!best || secHit > best.hit)) best = { hit: secHit, sec: sec };
        }
        if (inTitle) contribution += 8;
        if (inHeading) contribution += 5;
        if (inBody) contribution += 1;
        if (contribution === 0) matched = false; // every term must match somewhere
        total += contribution;
      }
      if (matched) out.push({ page: page, score: total, best: best, at: p });
    }
    out.sort(function (a, b) { return b.score - a.score || a.at - b.at; });
    return out.slice(0, MAX_RESULTS);
  }

  /* ---------- rendering (createElement only) ---------- */

  function text(parent, value) {
    parent.appendChild(document.createTextNode(value));
    return parent;
  }

  function snippet(source, terms) {
    // Window around the first term occurrence; "…" where trimmed.
    var lower = source.toLowerCase();
    var at = -1;
    var len = 0;
    for (var i = 0; i < terms.length; i++) {
      at = lower.indexOf(terms[i]);
      if (at !== -1) { len = terms[i].length; break; }
    }
    var frag = document.createDocumentFragment();
    if (at === -1) {
      text(frag, source.length > 170 ? source.slice(0, 170) + "…" : source);
      return frag;
    }
    var start = at > 70 ? at - 70 : 0;
    var end = Math.min(source.length, at + len + 100);
    if (start > 0) text(frag, "…");
    text(frag, source.slice(start, at));
    var mark = document.createElement("mark");
    mark.textContent = source.slice(at, at + len);
    frag.appendChild(mark);
    text(frag, source.slice(at + len, end));
    if (end < source.length) text(frag, "…");
    return frag;
  }

  function row(result, index, terms) {
    var page = result.page;
    var sec = result.best ? result.best.sec : null;
    var li = document.createElement("li");
    li.setAttribute("role", "presentation");
    var a = document.createElement("a");
    a.setAttribute("role", "option");
    a.id = "search-opt-" + index;
    a.tabIndex = -1;
    a.className = "search-result";
    a.href = BASE + page.url + (sec && sec.id ? "#" + sec.id : "");
    var head = document.createElement("span");
    head.className = "search-result-head";
    var title = document.createElement("span");
    title.className = "search-result-title";
    title.textContent = page.title;
    head.appendChild(title);
    if (sec && sec.heading) {
      var where = document.createElement("span");
      where.className = "search-result-section";
      where.textContent = sec.heading;
      head.appendChild(where);
    }
    a.appendChild(head);
    var snip = document.createElement("span");
    snip.className = "search-result-snippet";
    snip.appendChild(snippet(sec && sec.text ? sec.text : page.description, terms));
    a.appendChild(snip);
    li.appendChild(a);
    return li;
  }

  function setStatus(message) {
    var status = $("search-status");
    if (status) status.textContent = message;
  }

  function render(query) {
    var list = $("search-results");
    if (!list) return;
    list.textContent = "";
    ACTIVE = -1;
    RESULTS = [];
    var terms = query.toLowerCase().split(/\s+/).filter(Boolean);
    if (!INDEX || !terms.length) {
      setStatus("Type to search the documentation.");
      return;
    }
    RESULTS = score(query);
    if (!RESULTS.length) {
      setStatus("No results for \u201C" + query + "\u201D.");
      return;
    }
    var lastSection = null;
    for (var i = 0; i < RESULTS.length; i++) {
      if (RESULTS[i].page.section !== lastSection) {
        lastSection = RESULTS[i].page.section;
        var group = document.createElement("li");
        group.className = "search-group";
        group.setAttribute("role", "presentation");
        group.textContent = lastSection;
        list.appendChild(group);
      }
      list.appendChild(row(RESULTS[i], i, terms));
    }
    setStatus(RESULTS.length + (RESULTS.length === 1 ? " result" : " results"));
    setActive(0);
  }

  /* ---------- active option ---------- */

  function setActive(index) {
    var input = $("search-input");
    ACTIVE = RESULTS.length ? ((index % RESULTS.length) + RESULTS.length) % RESULTS.length : -1;
    for (var i = 0; i < RESULTS.length; i++) {
      var el = $("search-opt-" + i);
      if (el) {
        el.setAttribute("aria-selected", i === ACTIVE ? "true" : "false");
        if (i === ACTIVE) el.setAttribute("aria-selected", "true");
      }
    }
    if (input) {
      if (ACTIVE >= 0) {
        input.setAttribute("aria-activedescendant", "search-opt-" + ACTIVE);
        var active = $("search-opt-" + ACTIVE);
        if (active && active.scrollIntoView) active.scrollIntoView({ block: "nearest" });
      } else {
        input.removeAttribute("aria-activedescendant");
      }
    }
  }

  /* ---------- open / close ---------- */

  function open() {
    var overlay = $("search-overlay");
    var input = $("search-input");
    if (!overlay || !input) return;
    try { OPENER = document.activeElement; } catch (e) { OPENER = null; }
    overlay.hidden = false;
    if (document.body) document.body.classList.add("search-open");
    input.setAttribute("aria-expanded", "true");
    try { input.value = input.value || ""; } catch (e) { /* value intact */ }
    try { input.focus(); input.select(); } catch (e) { /* focus best effort */ }
    loadIndex(function (ok) {
      if (!ok) { close(); return; }
      render(input.value);
    });
  }

  function close() {
    var overlay = $("search-overlay");
    var input = $("search-input");
    if (!overlay) return;
    overlay.hidden = true;
    if (document.body) document.body.classList.remove("search-open");
    if (TIMER) { clearTimeout(TIMER); TIMER = null; }
    if (input) {
      input.setAttribute("aria-expanded", "false");
      input.removeAttribute("aria-activedescendant");
    }
    ACTIVE = -1;
    RESULTS = [];
    var opener = OPENER;
    OPENER = null;
    if (opener && opener.focus) {
      try { opener.focus(); } catch (e) { /* element gone */ }
    }
  }

  function isOpen() {
    var overlay = $("search-overlay");
    return !!overlay && !overlay.hidden;
  }

  /* ---------- wiring ---------- */

  ready(function () {
    try {
      var overlay = $("search-overlay");
      var input = $("search-input");
      var button = $("search-toggle");
      var closeBtn = $("search-close");
      if (!overlay || !input) return;
      BASE = overlay.getAttribute("data-baseurl") || "";

      if (button) {
        button.addEventListener("click", function () { try { if (isOpen()) close(); else open(); } catch (e) { /* inert */ } });
      }

      if (overlay) {
        overlay.addEventListener("click", function (ev) {
          try { if (ev.target === overlay) close(); } catch (e) { /* inert */ }
        });
      }

      if (closeBtn) {
        closeBtn.addEventListener("click", function () { try { close(); } catch (e) { /* inert */ } });
      }

      input.addEventListener("input", function () {
        try {
          if (TIMER) clearTimeout(TIMER);
          TIMER = setTimeout(function () {
            TIMER = null;
            try { if (INDEX) render(input.value); } catch (e) { /* inert */ }
          }, DEBOUNCE_MS);
        } catch (e) { /* inert */ }
      });

      input.addEventListener("keydown", function (ev) {
        try {
          if (ev.key === "ArrowDown") { ev.preventDefault(); setActive(ACTIVE + 1); }
          else if (ev.key === "ArrowUp") { ev.preventDefault(); setActive(ACTIVE - 1); }
          else if (ev.key === "Home") { ev.preventDefault(); setActive(0); }
          else if (ev.key === "End") { ev.preventDefault(); setActive(RESULTS.length - 1); }
          else if (ev.key === "Enter") {
            ev.preventDefault();
            if (ACTIVE >= 0) {
              var el = $("search-opt-" + ACTIVE);
              if (el && el.click) el.click();
            }
          } else if (ev.key === "Escape") { ev.preventDefault(); close(); }
        } catch (e) { /* keys stay native */ }
      });

      // Focus trap: Tab and Shift+Tab cycle input <-> close button.
      overlay.addEventListener("keydown", function (ev) {
        try {
          if (ev.key !== "Tab") return;
          ev.preventDefault();
          if (ev.shiftKey === (document.activeElement === input)) {
            if (closeBtn) closeBtn.focus();
          } else {
            input.focus();
          }
        } catch (e) { input.focus(); }
      });

      // Global shortcuts: Cmd/Ctrl+K toggles; "/" opens outside text
      // entry. Both are inert while typing in the search input itself
      // ("/" types a slash, K only acts with the modifier).
      document.addEventListener("keydown", function (ev) {
        try {
          var typing = false;
          var el = ev.target;
          if (el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" ||
                      el.tagName === "SELECT" || el.isContentEditable)) typing = true;
          var k = ev.key;
          if ((ev.metaKey || ev.ctrlKey) && !ev.altKey && (k === "k" || k === "K")) {
            ev.preventDefault();
            if (isOpen()) close(); else open();
          } else if (k === "/" && !ev.metaKey && !ev.ctrlKey && !ev.altKey && !typing) {
            ev.preventDefault();
            if (!isOpen()) open();
          }
        } catch (e) { /* shortcuts best effort */ }
      });
    } catch (e) { /* no search: the site works without it */ }
  });
})();
